/**
 * A small in-memory Proxmox VE API over real HTTPS, with a self-signed
 * certificate generated by openssl for each test run.
 *
 * It behaves like pveproxy where this provider depends on it:
 *  - API token auth (`PVEAPIToken=<id>=<secret>`), 401 otherwise;
 *  - chunked request bodies are refused (501), form bodies need a Content-Length;
 *  - errors carry Proxmox's message in the HTTP reason phrase;
 *  - a missing container answers 500 "Configuration file ... does not exist";
 *  - long operations return a UPID and run as tasks.
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { createServer, type Server } from "node:https";
import type { IncomingMessage, ServerResponse } from "node:http";
import { tmpdir } from "node:os";
import path from "node:path";
import type { AddressInfo } from "node:net";

export interface RecordedRequest {
  method: string;
  path: string;
  query: Record<string, string>;
  form: Record<string, string>;
  contentLength: string | undefined;
  chunked: boolean;
  authorization: string | undefined;
}

export interface FakeContainer {
  vmid: number;
  status: "running" | "stopped";
  config: Record<string, unknown>;
  /** Address the interfaces call reports once started. */
  ip: string | null;
  /** How many interfaces calls answer without an address after start (DHCP delay). */
  ipDelayCalls: number;
}

interface FakeTask {
  upid: string;
  exitstatus: string;
  log: string[];
}

export interface FakeProxmoxOptions {
  tokenId?: string;
  tokenSecret?: string;
  node?: string;
}

export class FakeProxmox {
  readonly tokenId: string;
  readonly tokenSecret: string;
  readonly node: string;
  readonly requests: RecordedRequest[] = [];
  readonly containers = new Map<number, FakeContainer>();
  readonly pools = new Set<string>(["epaperclip"]);
  readonly storages = new Set<string>(["local", "local-lvm"]);
  readonly volumes = new Set<string>(["local:vztmpl/debian-12-standard_12.12-1_amd64.tar.zst"]);
  readonly tasks = new Map<string, FakeTask>();
  nextVmid = 101;
  /** How many upcoming nextid answers are immediately taken by "another client". */
  racesOnNextId = 0;
  /** Exit status and log for the next task of a kind ("clone", "create", "start", ...). */
  readonly taskFailures = new Map<string, { exitstatus: string; log: string[]; leaveBehind?: boolean }>();
  /** Address given to the next started container. */
  nextIp = "10.10.0.50";
  caCert = "";
  private server: Server | null = null;
  private certDir: string | null = null;
  private taskCounter = 0;

  constructor(options: FakeProxmoxOptions = {}) {
    this.tokenId = options.tokenId ?? "epaperclip-engine@pve!sandbox";
    this.tokenSecret = options.tokenSecret ?? "00000000-1111-2222-3333-444444444444";
    this.node = options.node ?? "pve";
  }

  get url(): string {
    const address = this.server!.address() as AddressInfo;
    return `https://127.0.0.1:${address.port}`;
  }

  addTemplate(vmid: number, config: Record<string, unknown> = {}): void {
    this.containers.set(vmid, {
      vmid,
      status: "stopped",
      config: {
        hostname: "epaperclip-agent-template",
        template: 1,
        unprivileged: 1,
        cores: 2,
        memory: 2048,
        rootfs: "local-lvm:base-9000-disk-0,size=8G",
        net0: "name=eth0,bridge=vmbr0,hwaddr=BC:24:11:00:00:01,ip=dhcp,type=veth",
        ...config,
      },
      ip: null,
      ipDelayCalls: 0,
    });
  }

  addContainer(vmid: number, init: Partial<FakeContainer> & { config?: Record<string, unknown> }): FakeContainer {
    const container: FakeContainer = {
      vmid,
      status: init.status ?? "running",
      config: { hostname: `ct-${vmid}`, unprivileged: 1, ...(init.config ?? {}) },
      ip: init.ip ?? "10.10.0.77",
      ipDelayCalls: init.ipDelayCalls ?? 0,
    };
    this.containers.set(vmid, container);
    return container;
  }

  /** Requests matching a method and a path suffix. */
  find(method: string, pathSuffix: string | RegExp): RecordedRequest[] {
    return this.requests.filter(
      (r) => r.method === method && (typeof pathSuffix === "string" ? r.path.endsWith(pathSuffix) : pathSuffix.test(r.path)),
    );
  }

  async start(): Promise<void> {
    this.certDir = mkdtempSync(path.join(tmpdir(), "fake-pve-cert-"));
    const keyPath = path.join(this.certDir, "key.pem");
    const certPath = path.join(this.certDir, "cert.pem");
    execFileSync(
      "openssl",
      [
        "req", "-x509", "-newkey", "ec", "-pkeyopt", "ec_paramgen_curve:P-256", "-nodes",
        "-keyout", keyPath, "-out", certPath, "-days", "1",
        "-subj", "/CN=fake-pve", "-addext", "subjectAltName=IP:127.0.0.1",
      ],
      { stdio: "ignore" },
    );
    this.caCert = readFileSync(certPath, "utf8");
    this.server = createServer({ key: readFileSync(keyPath), cert: this.caCert }, (req, res) => {
      this.handle(req, res).catch((error) => this.fail(res, 500, String(error)));
    });
    await new Promise<void>((resolve) => this.server!.listen(0, "127.0.0.1", resolve));
  }

  async stop(): Promise<void> {
    if (this.server) await new Promise<void>((resolve) => this.server!.close(() => resolve()));
    this.server = null;
    if (this.certDir) rmSync(this.certDir, { recursive: true, force: true });
  }

  private reply(res: ServerResponse, data: unknown): void {
    const body = JSON.stringify({ data });
    res.writeHead(200, "OK", { "Content-Type": "application/json;charset=UTF-8", "Content-Length": Buffer.byteLength(body) });
    res.end(body);
  }

  private fail(res: ServerResponse, status: number, message: string, errors?: Record<string, string>): void {
    if (res.headersSent) return;
    const body = JSON.stringify({ data: null, ...(errors ? { errors } : {}) });
    // Proxmox puts its message in the reason phrase; it must be a single line.
    res.writeHead(status, message.replace(/[\r\n]+/g, " "), { "Content-Type": "application/json;charset=UTF-8", "Content-Length": Buffer.byteLength(body) });
    res.end(body);
  }

  private task(kind: string, vmid: number | string, onSuccess: () => void): string {
    this.taskCounter += 1;
    const upid = `UPID:${this.node}:000${this.taskCounter.toString(16).padStart(5, "0")}:00000000:6700${this.taskCounter}:${kind}:${vmid}:${this.tokenId}:`;
    const failure = this.taskFailures.get(kind);
    if (failure) {
      this.taskFailures.delete(kind);
      // A task can fail halfway and leave the half-made guest behind.
      if (failure.leaveBehind) onSuccess();
      this.tasks.set(upid, { upid, exitstatus: failure.exitstatus, log: [...failure.log, `TASK ERROR: ${failure.exitstatus}`] });
    } else {
      onSuccess();
      this.tasks.set(upid, { upid, exitstatus: "OK", log: [`${kind} ${vmid}`, "TASK OK"] });
    }
    return upid;
  }

  private missing(res: ServerResponse, vmid: number): void {
    this.fail(res, 500, `Configuration file 'nodes/${this.node}/lxc/${vmid}.conf' does not exist`);
  }

  private async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = new URL(req.url ?? "/", "https://fake");
    const chunks: Buffer[] = [];
    for await (const chunk of req) chunks.push(chunk as Buffer);
    const raw = Buffer.concat(chunks).toString("utf8");
    const chunked = /chunked/i.test(String(req.headers["transfer-encoding"] ?? ""));
    const form = Object.fromEntries(new URLSearchParams(raw));
    const query = Object.fromEntries(url.searchParams);
    const apiPath = url.pathname.replace(/^\/api2\/json/, "");
    this.requests.push({
      method: req.method ?? "GET",
      path: apiPath,
      query,
      form,
      contentLength: req.headers["content-length"],
      chunked,
      authorization: req.headers.authorization,
    });

    if (chunked) return this.fail(res, 501, "chunked transfer encoding not supported");
    if (req.headers.authorization !== `PVEAPIToken=${this.tokenId}=${this.tokenSecret}`) {
      return this.fail(res, 401, "invalid token value!");
    }
    if ((req.method === "POST" || req.method === "PUT") && raw.length > 0 && req.headers["content-length"] === undefined) {
      return this.fail(res, 411, "Length Required");
    }

    const method = req.method;
    let m: RegExpExecArray | null;
    if (method === "GET" && apiPath === "/version") return this.reply(res, { version: "8.4.1", release: "8.4", repoid: "2a5fa54a8503f96d" });
    if (method === "GET" && apiPath === "/cluster/nextid") {
      while (this.containers.has(this.nextVmid)) this.nextVmid += 1;
      const id = this.nextVmid;
      if (this.racesOnNextId > 0) {
        // Another client grabs the id right after we hand it out.
        this.racesOnNextId -= 1;
        this.addContainer(id, { status: "stopped", config: { tags: "someone-else" } });
      }
      return this.reply(res, String(id));
    }
    if (method === "GET" && (m = /^\/pools\/([^/]+)$/.exec(apiPath))) {
      const pool = decodeURIComponent(m[1]!);
      return this.pools.has(pool) ? this.reply(res, { members: [] }) : this.fail(res, 500, `pool '${pool}' does not exist`);
    }
    if ((m = /^\/nodes\/([^/]+)(\/.*)?$/.exec(apiPath))) {
      if (decodeURIComponent(m[1]!) !== this.node) return this.fail(res, 595, `no such cluster node '${m[1]}'`);
    }
    const nodePrefix = `/nodes/${this.node}`;
    const rest = apiPath.startsWith(nodePrefix) ? apiPath.slice(nodePrefix.length) : null;
    if (rest === null) return this.fail(res, 501, `Method '${method} ${apiPath}' not implemented`);

    if (method === "GET" && rest === "/status") return this.reply(res, { uptime: 12345, cpu: 0.02 });
    if (method === "GET" && (m = /^\/storage\/([^/]+)\/status$/.exec(rest))) {
      return this.storages.has(m[1]!) ? this.reply(res, { active: 1, enabled: 1, content: "rootdir,images" }) : this.fail(res, 500, `storage '${m[1]}' does not exist`);
    }
    if (method === "GET" && (m = /^\/storage\/([^/]+)\/content\/(.+)$/.exec(rest))) {
      const volid = decodeURIComponent(m[2]!);
      return this.volumes.has(volid) ? this.reply(res, { format: "tzst", size: 123 }) : this.fail(res, 500, `volume '${volid}' does not exist`);
    }
    if ((m = /^\/tasks\/([^/]+)\/(status|log)$/.exec(rest))) {
      const task = this.tasks.get(decodeURIComponent(m[1]!));
      if (!task) return this.fail(res, 500, "no such task");
      if (m[2] === "status") return this.reply(res, { status: "stopped", exitstatus: task.exitstatus, upid: task.upid });
      return this.reply(res, task.log.map((t, i) => ({ n: i + 1, t })));
    }

    if (method === "POST" && rest === "/lxc") {
      const vmid = Number(form.vmid);
      if (this.containers.has(vmid)) return this.fail(res, 500, `CT ${vmid} already exists on node '${this.node}'`);
      if (form.pool && !this.pools.has(form.pool)) return this.fail(res, 500, `pool '${form.pool}' does not exist`);
      return this.reply(res, this.task("vzcreate", vmid, () => {
        this.containers.set(vmid, {
          vmid,
          status: "stopped",
          config: {
            hostname: form.hostname,
            unprivileged: Number(form.unprivileged ?? 1),
            cores: Number(form.cores),
            memory: Number(form.memory),
            net0: form.net0,
            rootfs: form.rootfs,
            tags: form.tags,
            description: form.description,
          },
          ip: this.nextIp,
          ipDelayCalls: 0,
        });
      }));
    }

    if (!(m = /^\/lxc\/(\d+)(\/.*)?$/.exec(rest))) return this.fail(res, 501, `Method '${method} ${apiPath}' not implemented`);
    const vmid = Number(m[1]);
    const sub = m[2] ?? "";
    const ct = this.containers.get(vmid);

    if (method === "POST" && sub === "/clone") {
      if (!ct) return this.missing(res, vmid);
      const newid = Number(form.newid);
      if (this.containers.has(newid)) return this.fail(res, 500, `CT ${newid} already exists on node '${this.node}'`);
      if (form.pool && !this.pools.has(form.pool)) return this.fail(res, 500, `pool '${form.pool}' does not exist`);
      return this.reply(res, this.task("vzclone", vmid, () => {
        const config: Record<string, unknown> = { ...ct.config, hostname: form.hostname, description: form.description };
        delete config.template;
        this.containers.set(newid, { vmid: newid, status: "stopped", config, ip: this.nextIp, ipDelayCalls: 1 });
      }));
    }
    if (!ct) return this.missing(res, vmid);
    if (method === "GET" && sub === "/config") return this.reply(res, ct.config);
    if (method === "PUT" && sub === "/config") {
      Object.assign(ct.config, Object.fromEntries(Object.entries(form).map(([k, v]) => [k, /^\d+$/.test(v) ? Number(v) : v])));
      return this.reply(res, null);
    }
    if (method === "PUT" && sub === "/resize") return this.reply(res, this.task("resize", vmid, () => undefined));
    if (method === "GET" && sub === "/status/current") return this.reply(res, { status: ct.status, vmid, name: ct.config.hostname });
    if (method === "GET" && sub === "/interfaces") {
      if (ct.status !== "running") return this.fail(res, 500, `CT ${vmid} not running`);
      const lo = { name: "lo", hwaddr: "00:00:00:00:00:00", inet: "127.0.0.1/8" };
      if (ct.ipDelayCalls > 0 || !ct.ip) {
        ct.ipDelayCalls -= 1;
        return this.reply(res, [lo, { name: "eth0", hwaddr: "bc:24:11:aa:bb:cc" }]);
      }
      return this.reply(res, [lo, { name: "eth0", hwaddr: "bc:24:11:aa:bb:cc", inet: `${ct.ip}/24` }]);
    }
    if (method === "POST" && (m = /^\/status\/(start|shutdown|stop)$/.exec(sub))) {
      const action = m[1]!;
      if (action === "start" && ct.status === "running") return this.fail(res, 500, `CT ${vmid} already running`);
      if (action !== "start" && ct.status !== "running") return this.fail(res, 500, `CT ${vmid} not running`);
      return this.reply(res, this.task(`vz${action}`, vmid, () => {
        ct.status = action === "start" ? "running" : "stopped";
      }));
    }
    if (method === "DELETE" && sub === "") {
      if (ct.status === "running" && query.force !== "1") return this.fail(res, 500, `CT ${vmid} is running - destroy failed`);
      return this.reply(res, this.task("vzdestroy", vmid, () => this.containers.delete(vmid)));
    }
    return this.fail(res, 501, `Method '${method} ${apiPath}' not implemented`);
  }
}
